(function(root){
function cleanText(input,o={}){if(input.length>500000)throw Error('Văn bản tối đa 500.000 ký tự.');let text=input.replace(/\r\n?/g,'\n');if(o.normalize)text=text.normalize('NFC');if(o.nbsp)text=text.replace(/[\u00a0\u202f]/g,' ');if(o.invisible)text=text.replace(/[\u200b\u2060\ufeff\u00ad]/g,'');if(o.bidi)text=text.replace(/[\u061c\u200e\u200f\u202a-\u202e\u2066-\u2069]/g,'');let lines=text.split('\n');if(o.tabs&&(!Number.isInteger(Number(o.tabSize))||Number(o.tabSize)<1||Number(o.tabSize)>8))throw Error('Mỗi tab dùng từ 1 đến 8 dấu cách.');if(o.tabs)lines=lines.map(l=>l.replace(/\t/g,' '.repeat(Number(o.tabSize)||2)));if(o.collapse)lines=lines.map(l=>l.replace(/[ \t]+/g,' '));if(o.trim)lines=lines.map(l=>l.trim());if(o.empty==='remove')lines=lines.filter(l=>l.trim()!=='');if(o.empty==='collapse')lines=lines.filter((l,i)=>l.trim()!==''||i===0||lines[i-1].trim()!=='');if(o.outer){let first=0,last=lines.length;while(first<last&&lines[first].trim()==='')first++;while(last>first&&lines[last-1].trim()==='')last--;lines=lines.slice(first,last)}text=lines.join('\n');return{text,before:[...input].length,after:[...text].length,lines:text?text.split('\n').length:0,changed:text!==input};}
function httpURL(value,label='URL'){let u;try{u=new URL(value)}catch{throw Error(label+' phải là URL đầy đủ, ví dụ https://example.com/.')}if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error(label+' chỉ hỗ trợ HTTP/HTTPS và không chứa tài khoản/mật khẩu.');return u}
function robots(o){const agent=String(o.agent||'*').trim();if(!/^(?:\*|[a-zA-Z][a-zA-Z0-9_.-]{0,99})$/.test(agent))throw Error('User-agent chỉ gồm tên bot hoặc dấu *.');const lines=['# Generated by ToolHub','User-agent: '+agent];const paths=(value)=>{if(String(value||'').length>20000)throw Error('Danh sách đường dẫn quá dài.');return [...new Set(String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean))].map(p=>{if(!p.startsWith('/')||/[\s#\x00-\x1f]/.test(p))throw Error('Đường dẫn phải bắt đầu bằng /, không có khoảng trắng hoặc dấu #. Mã hóa khoảng trắng thành %20.');return p})};if(o.mode==='block')lines.push('Disallow: /');else if(o.mode==='open')lines.push('Disallow:');else if(o.mode==='custom'){const dis=paths(o.disallow),allow=paths(o.allow);if(!dis.length&&!allow.length)lines.push('Disallow:');for(const p of dis)lines.push('Disallow: '+p);for(const p of allow)lines.push('Allow: '+p)}else throw Error('Chọn chế độ hợp lệ.');const sitemaps=String(o.sitemaps||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(sitemaps.length>20)throw Error('Tối đa 20 sitemap.');for(const url of [...new Set(sitemaps)]){if(/[\s#\x00-\x1f]/.test(url))throw Error('Sitemap không được chứa khoảng trắng, xuống dòng hoặc fragment.');lines.push('Sitemap: '+httpURL(url,'Sitemap').href)}return lines.join('\n')+'\n';}
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function seo(o){const title=String(o.title||'').trim(),description=String(o.description||'').trim();if(title.length>1000||description.length>5000)throw Error('Tiêu đề tối đa 1.000, mô tả tối đa 5.000 ký tự.');if(!title)throw Error('Hãy nhập tiêu đề trang.');const url=httpURL(String(o.url||'').trim());const text='<title>'+escapeHTML(title)+'</title>\n<meta name="description" content="'+escapeHTML(description)+'">';return{title,description,url:url.href,host:url.host,path:url.pathname+url.search,titleCount:[...title].length,descriptionCount:[...description].length,html:text};}
function duration(hours,minutes,seconds){const values=[hours,minutes,seconds].map(Number);if([hours,minutes,seconds].some(x=>String(x).trim()==='')||values.some(x=>!Number.isInteger(x)||x<0)||values[0]>999||values[1]>59||values[2]>59)throw Error('Giờ từ 0–999; phút và giây từ 0–59, dùng số nguyên.');const ms=(values[0]*3600+values[1]*60+values[2])*1000;if(ms<1000)throw Error('Thời lượng phải ít nhất 1 giây.');return ms;}
function clockLabel(ms){const seconds=Math.ceil(Math.max(0,ms)/1000),h=Math.floor(seconds/3600),m=Math.floor(seconds/60)%60,s=seconds%60;return(h?String(h).padStart(2,'0')+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
class Timer{constructor(clock=()=>Date.now()){this.clock=clock;this.reset(0)}reset(ms=this.duration){this.duration=ms;this.rest=ms;this.deadline=null;this.state='idle'}remaining(){return this.state==='running'?Math.max(0,Math.min(this.rest,this.deadline-this.clock())):this.rest}start(ms){if(ms!==undefined){if(!Number.isFinite(ms)||ms<1000||ms>366*86400000)throw Error('Thời lượng từ 1 giây đến 366 ngày.');this.reset(ms)}if(this.state==='running')return;if(this.rest<=0)this.rest=this.duration;if(this.rest<=0)throw Error('Hãy đặt thời lượng.');this.deadline=this.clock()+this.rest;this.state='running'}pause(){if(this.state==='running'){this.rest=this.remaining();this.deadline=null;this.state=this.rest===0?'finished':'paused'}}update(){if(this.state==='running'&&this.remaining()===0){this.rest=0;this.deadline=null;this.state='finished';return true}return false}}
root.ToolHubDailyCore={cleanText,robots,seo,duration,clockLabel,Timer};
})(globalThis);
